  "ui.wpAdminAgentFrameApp.feedback106": "Текущий документ Gutenberg доступен только как привязанный снимок, разбитый на части. Нельзя подготовить изменение всего документа, пока не прочитаны все необходимые части. Я ничего не изменил.",
  "ui.wpAdminAgentFrameApp.feedback107": "В текущей записи Gutenberg есть несохранённые изменения. Сохраните или обновите её, прежде чем Pixflow прочитает её или подготовит правку с учётом содержимого. Я ничего не изменил.",
