  "wp.message.26a6374fbf59": "Не удалось запустить дополнение Pixflow. Проверьте совместимость плагинов Pixflow и перезагрузите страницу. Другие функции могут оставаться доступными.",
  "wp.message.ca7714cffbcc": "Активировать Pro",
  "wp.message.197c83a2f752": "Верните расширенные инструменты с дополнением Pro. Лицензия, содержимое и сохранённые настройки останутся на месте. Если вы использовали двухфакторную аутентификацию Bricks, включите её снова в настройках после активации Pro.",
  "wp.message.2ffdcbc380ea": "Создавайте в любимом конструкторе. Добавьте в свой рабочий процесс аннотации, голос, дизайн-системы и генерацию изображений.",
  "wp.message.40ed1102964b": "Проверить пробный период Pro",
  "wp.message.e9cccd3ef5fc": "Не удалось сохранить закрытие уведомления. Повторите попытку.",
  "wp.message.1372089fb797": "Закрыть баннер Pixflow Pro",
  "wp.message.5e3ba715018d": "Скачать Pro",
  "wp.message.fb2e6d87b44c": "Больше возможностей с Pixflow Design Pro",
  "wp.message.9934717ca744": "Обновите страницу и повторите попытку.",
  "wp.message.7c78f9990490": "Начать 7-дневный пробный период Pro",
  "wp.message.f89b4dcf2c2e": "Попробовать Pro 7 дней",
  "wp.message.69ecce9deb2d": "Вы не можете закрыть это уведомление.",
  "wp.message.927384e7eed8": "Ваш тариф Pixflow включает Pro",
