  "ui.finalDesignFlow.6ec10e401c": "Отклонено. Текущая дизайн-система осталась без изменений.",
  "ui.finalDesignFlow.2481c9bd1e": "Я готовлю пересборку контракта токенов для проверки. Активный контракт не изменится до принятия доработки.",
  "ui.finalDesignFlow.c5e57eef36": "Я применяю ваши замечания к дизайн-системе. Пока идёт доработка, вы можете продолжать проверять текущий черновик.",
  "ui.finalDesignFlow.def81ed84f": "Я создаю рабочую область дизайн-системы, карточки предпросмотра и вспомогательные файлы на основе предоставленного вами контекста.",
