  "ui.finalDesignFlow.d461a493a3": "Автоматически",
  "ui.finalDesignFlow.0e94726136": "Доступ инструментов агента через коннектор GitHub в Composio; URL репозиториев по-прежнему работают с локальным git или GitHub CLI.",
  "ui.finalDesignFlow.723772b0a0": "Добавьте API-ключ Composio, только если проекту нужны инструменты GitHub через коннектор.",
  "ui.finalDesignFlow.21f5844795": "Коннектор GitHub в Composio доступен как запасной вариант, если это устройство не может прочитать репозиторий.",
  "ui.finalDesignFlow.f32b39ae4f": "Завершите авторизацию в окне Composio; локальный импорт из GitHub остаётся доступным.",
  "ui.finalDesignFlow.2a0d6e82a3": "Статус коннектора проверяется в фоне; импорт по URL не заблокирован.",
  "ui.finalDesignFlow.5d652ac7d4": "Повторно подключите коннектор GitHub в Composio или продолжите с локальным git/GitHub CLI.",
  "ui.finalDesignFlow.c8f1da9e35": "Обновите эту дизайн-систему: ",
