  "ui.finalExport.printFailed": "Не удалось выполнить печать. Повторите экспорт в PDF или используйте версию для браузера.",
  "ui.finalExport.popupBlocked": "Браузер заблокировал окно экспорта. Разрешите всплывающие окна для этого сайта и повторите экспорт в PDF.",
  "ui.finalOnboarding.f54f5d4bcd": "Ваша настройка",
  "ui.finalOnboarding.7d2d594053": "Как вы хотите использовать Pixflow?",
  "ui.finalOnboarding.bdf73477f9": "Подключите своего API-провайдера",
  "ui.finalOnboarding.28edc3b8f2": "Подключите свою подписку на ИИ",
  "ui.finalOnboarding.f9573d1164": "Всё готово к работе",
  "ui.finalOnboarding.45ddd1221b": "Редактирование WordPress и Gutenberg бесплатно. Лицензия или пробный период не нужны.",
  "ui.finalOnboarding.6072f06060": "Активируйте лицензию, чтобы начать. Уже активировали? Лицензия появится здесь.",
  "ui.finalOnboarding.ae83bc42b4": "Выберите подходящий вариант. Его можно изменить в настройках в любое время.",
  "ui.finalOnboarding.c9e2eb7fcb": "Используйте API-ключ своего провайдера. Для этого режима Bridge не нужен.",
  "ui.finalOnboarding.5add76d77c": "Bridge связывает этот сайт с ИИ-агентами на вашем компьютере. Использование ИИ обеспечивается учётной записью провайдера.",
  "ui.finalOnboarding.4813d31d25": "Используйте рабочую область WordPress без подключения ИИ.",
  "ui.finalOnboarding.fbcd710247": "Подключение настроено. Задайте вопрос или опишите, что хотите создать.",
  "ui.finalOnboarding.24fba6f166": "Подключить подписку на ИИ",
  "ui.finalOnboarding.82d6b8daef": "Используйте поддерживаемые агенты, например Codex или OpenCode, через Pixflow Design Bridge.",
  "ui.finalOnboarding.894f66ba11": "Использовать API-ключ",
  "ui.finalOnboarding.e76c3bfd0e": "Подключитесь напрямую к провайдеру. Использование API оплачивается отдельно.",
  "ui.finalOnboarding.1be451ef72": "Продолжить без ИИ",
  "ui.finalOnboarding.88e6e83b86": "Используйте рабочую область WordPress. При желании подключите ИИ позже.",
  "ui.finalOnboarding.105e56e56f": "Зачем выбирать локальный CLI?",
  "ui.finalOnboarding.5df057fcd7": "Использование API оплачивается отдельно",
  "ui.finalOnboarding.44e30ed15f": "Для BYOK нужен API-ключ. Провайдер ИИ взимает плату за API отдельно от подписки CLI, поэтому могут возникнуть дополнительные расходы вместо использования включённых или недельных лимитов учётной записи CLI.",
  "ui.finalOnboarding.5f9b0ae108": "Только сеанс",
  "ui.finalOnboarding.3c0e1f05da": "Хранить контекст только пока открыт этот сеанс панели. После перезагрузки всё начинается заново.",
  "ui.finalOnboarding.3efe5537cf": "Восстановить после перезагрузки",
  "ui.finalOnboarding.1ccaa4f4ad": "Восстановить ограниченный контекст после перезагрузки этой вкладки браузера.",
  "ui.finalOnboarding.a7f9620cca": "На этом устройстве",
  "ui.finalOnboarding.94536fb7d6": "Хранить ограниченный локальный контекст между перезапусками браузера на этом устройстве.",
  "ui.finalOnboarding.1cd7c231fc": "Настройки хранения плавающей панели обновлены.",
