  "ui.seoAudit.useCustomSettings_afa7c63e": "Использовать пользовательские настройки",
  "ui.seoAudit.aClientReportCanPredateSeveral_d76aee45": "Отчет клиента может предшествовать нескольким аудитам. Только поле «Последний начатый аудит», которое указывает на дату начала предыдущего аудита, позволяет определить его. Используйте текущий план действий для рекомендаций. Необходимо разделять отчет и интервалы проведения аудитов. Предыдущие комментарии содержат предыдущие рекомендации, а не авторитетные измерения: они могут содержать информацию даже из более старых отчетов. Используйте отметки времени для подтверждения выполненной работы. Отсутствие или нерелевантность проверки не является решением проблемы.",
