  "ui.seoAudit.boundedAnonymousHttpVerificationIncludingRedirects_9e6b6a1f": "Проверка через HTTP, включая перенаправления, с использованием анонимных URL. URL, которые не были проверены и исключены, не проходят проверку.",
  "ui.seoAudit.boundedExternalHttpVerificationRespectingRobots_54b3457f": "Проверка через HTTP, с соблюдением политики robots, ограничений на запросы и ограничений на использование хостов.",
  "ui.seoAudit.boundedFiveWordShingleSimilarityOf_1fc8d930": "Ограничение сравнения текста до пяти слов, исключая стандартные псевдонимы и указанные разные языки. Само по себе сравнение не является достаточным основанием для переписывания.",
  "ui.seoAudit.boundedRedirectAwareDestinationVerificationReachability_3e12245a": "Проверка целевого адреса с учетом перенаправлений; достижимость не доказывает выбор Google в качестве основного.",
  "ui.seoAudit.browserCoverageObservedObservedViewportSamples_c9c88985": "Объем проверки: {observed} – просмотр образцов, полученных из окна браузера; {unavailable} – недоступно. Последний образец для каждого URL и окна браузера. Ограниченное наблюдение за DOM, не охватывающее весь JavaScript, визуальный анализ пикселей, измерения реальных пользователей или подтвержденные исправления.",
  "ui.seoAudit.browserMeasurementsPagespeedAndCruxAre_c2f3cc1b": "Измерения в браузере, PageSpeed и CrUX – это отдельные этапы, отличные от этого сканирования HTML.",
  "ui.seoAudit.browserSelectionSelectedOfEligibleEligible_66bfffef": "Выбор страниц: страницы, соответствующие критериям {selected} и {eligible}, из наборов {represented} и {families}. Выбор не приводит к успешной проверке. Страницы, не включенные в выбор, остаются не проверенными браузером; их отдельные HTML-результаты сохраняются.",
  "ui.seoAudit.canonicalAliasesAreExcludedFromThis_f8402c0a": "Канонические алиасы исключены из этого сравнения.",
  "ui.seoAudit.characterCountsOnlyNotGoogleSnippet_3f4c790a": "Только количество символов, а не ширина фрагмента Google или требования к ранжированию.",
  "ui.seoAudit.chooseAPngJpegOrWebp_4b4e7850": "Выберите логотип в формате PNG, JPEG или WebP размером до 5 МБ.",
  "ui.seoAudit.confirmThePagesServeDifferentPurposes_f74de763": "Убедитесь, что страницы имеют разные цели, прежде чем редактировать их.",
  "ui.seoAudit.correctTheCanonicalInItsOwning_6263cd04": "Исправьте каноническую ссылку в настройках SEO, относящихся к этой странице, после подтверждения, что страница предназначена для индексации. Не восстанавливайте страницу, которая была исключена из индекса.",
