  "ui.seoAudit.depthAndIncomingLinksWithinThe_4b14a76f": "Глубина и входящие ссылки в просмотренной графе. Отсутствие входящих ссылок – это кандидаты на определение \"орфанной\" страницы, а не доказательство её \"орфанности\".",
  "ui.seoAudit.destinationVerificationReachedItsRecheckBudget_077d5a77": "Проверка целевых страниц достигла лимита повторной проверки. Необходимо провести новую проверку.",
