  "ui.seoAudit.distinctCanonicalDocumentsInTheInspected_31e34780": "Различные \"основные\" документы в просмотренном наборе; для документов с совпадающими заголовками требуется проверка намерений.",
  "ui.seoAudit.earlierRepairsPassingStillPassingReturned_d38c3063": "Предыдущие исправления: {passing} всё ещё проходят проверку, {returned} возвращены, {review} ожидают повторной проверки.",
  "ui.seoAudit.exactMainArticleTextOfAt_b4c8d313": "Точный основной/статья текст, содержащий не менее 80 слов. Документы с похожим текстом и без основной/статьи не сравниваются.",
