  "ui.seoAudit.reconciledEligibleInventoryAndInspectedHtml_16a615aa": "Проверены и сопоставлены доступные данные, а также проверены HTML-ссылки. Страницы, намеренно оставленные без ссылок, требуют решения владельца; частичные сканирования не могут установить статус \"орфанной\" страницы.",
  "ui.seoAudit.redirect_171a1065": "Перенаправление",
  "ui.seoAudit.reportedContentTypeCachingAndCompression_b05cc491": "Указаны типы контента, заголовки кэширования и сжатия. Отсутствие заголовков само по себе не является ошибкой.",
  "ui.seoAudit.reviewThesePagesTogetherKeepLegitimate_1d5fd748": "Просмотрите эти страницы вместе. Сохраните допустимые общие формулировки и канонические псевдонимы. Изменяйте метаданные или контент только тогда, когда страницы выполняют различные функции, и это изменение приносит пользу пользователям.",
  "ui.seoAudit.runANewSiteAuditTo_0a66a536": "Проведите новый аудит сайта, чтобы обновить полную сравнительную таблицу. Одна страница не может проверить охват всего сайта.",
  "ui.seoAudit.sectionIdsInCompleteStaticHtml_ffb834de": "Идентификаторы разделов в полностью статичном HTML. Отсутствующие идентификаторы в документах, зависящих от JavaScript или содержащих неполную информацию, остаются не проверенными.",
  "ui.seoAudit.theAgentReturnedIncompleteChoicesOpen_d075ada3": "Агент вернул неполный набор вариантов. Нажмите \"Выбрать следующий шаг\", чтобы повторить попытку.",
  "ui.seoAudit.theAuditCouldNotStartCheck_61904628": "Аудит не может быть запущен. Проверьте статус провайдера, страницы и аудита, а затем попробуйте снова.",
  "ui.seoAudit.theAuditIsBusySavingAnother_52b4eaf0": "Аудит занят сохранением другой проверки. Повторите проверку в браузере, чтобы продолжить; сохраненный прогресс будет сохранен.",
  "ui.seoAudit.theBannerCouldNotBeDismissed_73eac8ff": "Невозможно было удалить баннер.",
