  "ui.seoAudit.theSourcePageCouldNotBe_356fcd92": "Невозможно было полностью проверить исходную страницу.",
  "ui.seoAudit.thisCheckNeedsMoreThanTen_6648ef0b": "Для проведения проверки требуется более десяти новых целевых адресов. Необходимо провести новую проверку для подтверждения всей группы.",
  "ui.seoAudit.twoAnonymousGzipNegotiatedRequestsFor_083df39d": "Две анонимные запросы, использующие gzip, для проверки до трех страниц. Сигналы попадания в кэш и подтвержденное использование gzip – это не показатели скорости, а результаты проверки.",
  "ui.seoAudit.undone_dcccf568": "Отменено",
