  "ui.seoAudit.updateOnlyTheReferringLinksOn_7b067b7c": "Обновляйте только ссылки, ведущие на эту страницу, после подтверждения правильности целевых адресов. Сохраняйте намеренно удаленные HTTP 410 адреса.",
  "ui.seoAudit.verifyHttpsAvailabilityForEachNamed_f47c0944": "Проверьте доступность HTTPS для каждого указанного ресурса и обновите соответствующую настройку владельца или активов. Сохраните исходный макет и медиафайлы.",
